def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token not in {"+", "-", "*", "/"}:
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division truncates toward zero
                # Python int division truncates toward zero when using int(a / b)
                res = int(a / b)
            stack.append(res)
    return stack[-1]

