{"task_id": "T25", "code": "def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses exact arithmetic with Fraction to avoid floating point errors.
    Returns 0 for empty matrix (as per typical problem expectations).
    """
    from fractions import Fraction
    n = len(matrix)
    if n == 0:
        return 0
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Copy as Fraction matrix
    a = [[Fraction(matrix[i][j]) for j in range(n)] for i in range(n)]
    det = Fraction(1)
    sign = 1
    for col in range(n):
        # Find pivot
        pivot = None
        for row in range(col, n):
            if a[row][col] != 0:
                pivot = row
                break
        if pivot is None:
            return 0
        if pivot != col:
            a[col], a[pivot] = a[pivot], a[col]
            sign *= -1
        pivot_val = a[col][col]
        det *= pivot_val
        # Eliminate below
        for row in range(col + 1, n):
            factor = a[row][col] / pivot_val
            if factor == 0:
                continue
            for k in range(col, n):
                a[row][k] -= factor * a[col][k]
    det *= sign
    return int(det)
"}

