from fractions import Fraction

def solve(m):
    # Exact Gaussian elimination over the rationals.
    # det = sign * product of pivots; exact for integer (and rational/float) inputs.
    n = len(m)
    if n == 0:
        return 1
    a = [[Fraction(x) for x in row] for row in m]
    sign = 1
    prod = Fraction(1)
    for k in range(n):
        if a[k][k] == 0:
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    sign = -sign
                    break
            else:
                return 0  # whole column below pivot is zero
        pivot = a[k][k]
        prod *= pivot
        for i in range(k + 1, n):
            f = a[i][k] / pivot
            if f:
                row_i = a[i]
                row_k = a[k]
                for j in range(k + 1, n):
                    row_i[j] -= f * row_k[j]
    det = sign * prod
    if det.denominator == 1:
        return int(det)
    return float(det)  # only reachable for non-integer (e.g. float) inputs

