def solve(s) -> bool:
    """Validate an IPv4 address.

    The function is tolerant of non‑string inputs: ``None`` or other types are
    converted to ``str`` (with ``None`` becoming an empty string).  Leading and
    trailing whitespace is stripped.  The validation follows the specification:

    * Exactly four decimal parts separated by '.'
    * Each part is an integer in the range 0‑255
    * No leading zeros are allowed except for the single digit ``0``
    * Only digits are permitted.
    """
    # Normalise input
    if s is None:
        return False
    if not isinstance(s, str):
        try:
            s = str(s)
        except Exception:
            return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        # No leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        if not part.isdigit():
            return False
        try:
            val = int(part)
        except ValueError:
            return False
        if val < 0 or val > 255:
            return False
    return True

